def tally_votes(votes: list[str]) -> list[str]:
    if not votes:
        return []

    # 各候補者の得票数と最初の出現位置を記録
    count = {}
    first_occurrence = {}

    for index, candidate in enumerate(votes):
        count[candidate] = count.get(candidate, 0) + 1
        if candidate not in first_occurrence:
            first_occurrence[candidate] = index

    # 得票数で降順、同じなら最初の出現位置で昇順にソート
    sorted_candidates = sorted(
        count.keys(),
        key=lambda x: (-count[x], first_occurrence[x])
    )

    return sorted_candidates
