def next_bus(times: list[str], now: str) -> str:
    # 時刻文字列を分単位に変換して比較しやすくする
    def time_to_minutes(t: str) -> int:
        h, m = map(int, t.split(':'))
        return h * 60 + m

    # 全ての時刻を分単位に変換
    now_minutes = time_to_minutes(now)
    times_minutes = [time_to_minutes(t) for t in times]

    # 今日の便（now以降）を探す
    for t in times_minutes:
        if t >= now_minutes:
            # 見つかったら元の文字列形式で返す
            for original in times:
                if time_to_minutes(original) == t:
                    return original

    # 今日の便がなければ、翌日の最初の便（最も早い時刻）
    # 最も早い時刻を見つける（最小値）
    earliest = min(times_minutes)
    for original in times:
        if time_to_minutes(original) == earliest:
            return original
