def bracket_depth(s: str) -> int:
    stack = []
    max_depth = 0
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
            max_depth = max(max_depth, len(stack))
        elif char in ')]}':
            if not stack or stack.pop() != mapping[char]:
                return -1

    if stack:
        return -1

    return max_depth
```

