def bracket_depth(s: str) -> int:
    stack = []
    max_depth = 0
    for char in s:
        if char in '({[':
            stack.append(char)
            max_depth = max(max_depth, len(stack))
        elif char in ')}]':
            if not stack:
                return -1
            open_bracket = stack.pop()
            if not ((char == ')' and open_bracket == '(') or
                    (char == '}' and open_bracket == '{') or
                    (char == ']' and open_bracket == '[')):
                return -1
    if stack:
        return -1
    return max_depth
```

